    {   "from": [ 7, 1, 7 ],
      "to": [ 9, 11, 9 ],
      "rotation": { "origin": [ 8, 1, 8 ], "axis": "x", "angle": -45 },
      "faces": {
        "up":    { "uv": [ 7, 6, 9,  8 ], "texture": "#lever" },
        "north": { "uv": [ 7, 6, 9, 16 ], "texture": "#lever" },
